import { useState } from 'react';

const IMAGES = ['car1.jpg', 'car2.jpg', 'car3.jpg', 'car4.jpg', 'car5.jpg'];

function AddVehicle({ user, onAdded }) {
  const [form, setForm] = useState({
    brand: '',
    model: '',
    segment: 'Economy',
    pricePerDay: '',
    campus: '',
    image: '',
  });
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setSuccess('');
    try {
      const res = await fetch('http://localhost:3002/api/vehicles', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...form, ownerId: user.id }),
      });
      if (res.ok) {
        setSuccess('Araç başarıyla eklendi!');
        setForm({ brand: '', model: '', segment: 'Economy', pricePerDay: '', campus: '', image: '' });
        onAdded();
        setTimeout(() => setSuccess(''), 3000);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="add-vehicle">
      <h2>Araç Ekle</h2>
      <form onSubmit={handleSubmit} className="add-vehicle-form">
        <input
          placeholder="Marka (örn: Toyota)"
          value={form.brand}
          onChange={(e) => setForm({ ...form, brand: e.target.value })}
          required
        />
        <input
          placeholder="Model (örn: Corolla)"
          value={form.model}
          onChange={(e) => setForm({ ...form, model: e.target.value })}
          required
        />
        <select
          value={form.segment}
          onChange={(e) => setForm({ ...form, segment: e.target.value })}
        >
          <option value="Economy">Economy</option>
          <option value="Standard">Standard</option>
          <option value="Premium">Premium</option>
          <option value="SUV">SUV</option>
        </select>
        <input
          type="number"
          placeholder="Günlük fiyat (₺)"
          value={form.pricePerDay}
          onChange={(e) => setForm({ ...form, pricePerDay: e.target.value })}
          required
        />
        <input
          placeholder="Kampüs (örn: Yaşar Üniversitesi)"
          value={form.campus}
          onChange={(e) => setForm({ ...form, campus: e.target.value })}
          required
        />

        <div className="image-picker-label">Araç Görseli Seç</div>
        <div className="image-picker">
          {IMAGES.map((img) => (
            <div
              key={img}
              className={`image-option ${form.image === img ? 'selected' : ''}`}
              onClick={() => setForm({ ...form, image: img })}
            >
              <img src={`/images/${img}`} alt={img} />
              {form.image === img && <div className="image-check">✓</div>}
            </div>
          ))}
        </div>

        {success && <p className="success">{success}</p>}
        <button type="submit" disabled={loading}>
          {loading ? 'Ekleniyor...' : 'Araç Ekle'}
        </button>
      </form>
    </div>
  );
}

export default AddVehicle;
